# ==================== 辅助函数 ====================

def contains_chinese(text):
    """检查文本是否包含中文"""
    if not isinstance(text, str):
        return False
    return bool(re.search(r'[\u4e00-\u9fff]', text))

def apply_translations(data):
    """应用翻译到数据结构"""
    if isinstance(data, dict):
        new_data = {}
        for key, value in data.items():
            # 翻译键名（H1项目奖 -> H1 Project Awards等）
            if key in award_type_translations:
                new_key = award_type_translations[key]
            else:
                new_key = key
            
            # 翻译值
            if isinstance(value, str):
                translated_value = value
                # 翻译项目名
                if value in project_name_translations:
                    translated_value = project_name_translations[value]
                # 翻译团队奖名
                elif value in team_award_translations:
                    translated_value = team_award_translations[value]
                # 翻译获奖理由
                elif value in reason_translations:
                    translated_value = reason_translations[value]
                # 翻译奖项类型
                elif value in award_type_translations:
                    translated_value = award_type_translations[value]
                new_data[new_key] = translated_value
            elif isinstance(value, list):
                new_data[new_key] = [apply_translations(item) if isinstance(item, (dict, list)) else item for item in value]
            else:
                new_data[new_key] = value
        return new_data
    elif isinstance(data, list):
        return [apply_translations(item) if isinstance(item, (dict, list)) else item for item in data]
    else:
        return data

def translate_file(filepath):
    """翻译单个JSON文件"""
    print(f"Processing {filepath}...")
    
    with open(filepath, 'r', encoding='utf-8') as f:
        data = json.load(f)
    
    translated_data = apply_translations(data)
    
    with open(filepath, 'w', encoding='utf-8') as f:
        json.dump(translated_data, f, ensure_ascii=False, indent=2)
    
    print(f"✓ Translated {filepath}")

def main():
    # 翻译映射文件保存
    all_translations = {
        "project_name": project_name_translations,
        "team_award": team_award_translations,
        "award_type": award_type_translations,
        "reason": reason_translations
    }
    
    with open('/tmp/all_translations.json', 'w', encoding='utf-8') as f:
        json.dump(all_translations, f, ensure_ascii=False, indent=2)
    print("Saved translation mapping to /tmp/all_translations.json")
    
    # 应用翻译到所有JSON数据文件
    data_dir = "data"
    files = ['eu.json', 'fs.json', 'global.json', 'pop.json', 'sea.json', 'us.json', 'departmental.json', 'latam.json']
    
    for filename in files:
        filepath = os.path.join(data_dir, filename)
        if os.path.exists(filepath):
            translate_file(filepath)
    
    print("\n✅ All data files translated!")

if __name__ == "__main__":
    main()
